/**
 * Replay state classification (architecture L8).
 *
 * REGENERATED by replay (constructive, produced by recorded steps): entities, order, selection, materials, components, constraints(+Order),
 * joints(+Order), driveRelations(+Order), featureHistory. CARRIED from base (document-level inputs written by metaHistory commands):
 * camera, units, displayPrecision, parameters, animations, groups, layers, layerOrder, configurations, recipes. ORPHANS: entries in a
 * regenerated table that no base history step produced (e.g. loaded or seeded outside history). They would be lost by replay, so they are
 * seeded into the fresh document.
 */

import type { CadDocument, FeatureStep } from '../../model/types';

function affectedIds(history: FeatureStep[]): Set<string> {
  const ids = new Set<string>();
  for (const step of history) for (const id of step.affected ?? []) ids.add(id);
  return ids;
}

function paramString(step: FeatureStep, key: string): string | undefined {
  const params: unknown = step.params;
  if (typeof params !== 'object' || params === null) return undefined;
  const value = (params as Record<string, unknown>)[key];
  return typeof value === 'string' ? value : undefined;
}

/**
 * Whether replay regenerates material `name` instead of carrying it: `create_material` (params.name), `define_material_record` (params.id), or a
 * record of an imported library (only `import_material_library` produces those; a suppressed or deleted import step must not leave its values behind).
 * @invariant `materialLibraries` is never carried: library entries and their records come back only from their import step
 */
function ownsMaterial(history: readonly FeatureStep[], name: string, material: CadDocument['materials'][string]): boolean {
  if (material.record?.libraryRef !== undefined) return true;
  return history.some(
    (s) =>
      (s.name === 'create_material' && paramString(s, 'name') === name) ||
      (s.name === 'define_material_record' && paramString(s, 'id') === name),
  );
}

/** The records of an ordered table that no history step produced, with their order. */
function orphanRecords<T>(
  table: Readonly<Record<string, T>>,
  order: readonly string[],
  affected: ReadonlySet<string>,
): { records: Record<string, T>; order: string[] } {
  const ids = order.filter((id) => !affected.has(id) && id in table);
  return { records: Object.fromEntries(ids.map((id) => [id, table[id] as T])), order: ids };
}

export function orphanState(
  base: CadDocument,
): Pick<
  CadDocument,
  'materials' | 'components' | 'constraints' | 'constraintOrder' | 'joints' | 'jointOrder' | 'driveRelations' | 'driveRelationOrder'
> {
  const history = base.featureHistory;
  const affected = affectedIds(history);
  const materials = Object.fromEntries(Object.entries(base.materials).filter(([key, material]) => !ownsMaterial(history, key, material)));
  const componentSteps = history.filter((s) => s.name === 'create_component');
  const componentClaims = new Set<string | undefined>();
  let unattributable = 0;
  for (const step of componentSteps) {
    const explicit = paramString(step, 'componentId');
    if (explicit !== undefined) {
      componentClaims.add(explicit);
      continue;
    }
    const instance = step.affected?.[0] !== undefined ? base.entities[step.affected[0]] : undefined;
    if (instance?.kind === 'instance') componentClaims.add(instance.componentId);
    else unattributable++;
  }
  const components =
    unattributable > 0 ? {} : Object.fromEntries(Object.entries(base.components).filter(([key]) => !componentClaims.has(key)));
  const constraints = orphanRecords(base.constraints, base.constraintOrder, affected);
  const joints = orphanRecords(base.joints, base.jointOrder, affected);
  const driveRelations = orphanRecords(base.driveRelations, base.driveRelationOrder, affected);
  return {
    materials,
    components,
    constraints: constraints.records,
    constraintOrder: constraints.order,
    joints: joints.records,
    jointOrder: joints.order,
    driveRelations: driveRelations.records,
    driveRelationOrder: driveRelations.order,
  };
}
